type Entry = { readonly sha256: string; readonly path: string };

function entriesOf(text: string): Entry[] {
  const out: Entry[] = [];
  for (const line of text.split('\n')) {
    const m = /^([0-9a-f]{64}) {2}(\S.*)$/.exec(line);
    if (m) out.push({ sha256: m[1] ?? '', path: m[2] ?? '' });
  }
  return out;
}

function walk(dir: string): string[] {
  const out: string[] = [];
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const full = join(dir, entry.name);
    if (entry.isDirectory()) out.push(...walk(full));
    else out.push(relative(HARNESS_CODEX_DIR, full).split(sep).join('/'));
  }
  return out;
}

const MANIFEST_BYTES = readFileSync(join(HARNESS_CODEX_DIR, 'pin', 'MANIFEST.sha256'));
const MANIFEST_TEXT = MANIFEST_BYTES.toString('utf8');
const WIRE_BYTES = readFileSync(join(HARNESS_CODEX_DIR, 'protocol', 'wire.ts'));

describe('C12-R1 — wire/MANIFEST one-entry rebind', () => {
  it('covers exactly 14 client methods (COVERED_METHOD_COUNT === 14), experimentalFeature/list last', () => {
    expect(CODEX_COVERED_CLIENT_METHODS).toHaveLength(14);
    expect(CODEX_COVERED_CLIENT_METHODS.at(-1)).toBe('experimentalFeature/list');
  });

  it('keeps 717 manifest entries, and exactly one of them (protocol/wire.ts) differs from the embedded baseline copy', () => {
    expect(BASELINE_MANIFEST_ENTRIES).toHaveLength(717);
    const baseline = BASELINE_MANIFEST_ENTRIES.map((line) => entriesOf(line)[0]!);
    const current = entriesOf(MANIFEST_TEXT);
    expect(current).toHaveLength(717);
    expect(current.map((e) => e.path)).toEqual(baseline.map((e) => e.path));
    const differing = current.filter((e, i) => e.sha256 !== baseline[i]!.sha256);
    expect(differing.map((e) => e.path)).toEqual(['protocol/wire.ts']);
    expect(baseline.find((e) => e.path === 'protocol/wire.ts')!.sha256).toBe(BASELINE_WIRE_DIGEST);
    expect(differing[0]!.sha256).toBe(sha256(WIRE_BYTES));
    expect(differing[0]!.sha256).not.toBe(BASELINE_WIRE_DIGEST);
  });

  it('changes no other manifest byte: restoring the baseline wire digest reproduces the baseline manifest exactly', () => {
    const lines = MANIFEST_TEXT.split('\n');
    const at = lines.findIndex((l) => l.endsWith('  protocol/wire.ts'));
    expect(at).toBeGreaterThan(0);
    expect(lines[at - 1]).toBe("# src DERIVED VERBATIM_SOURCE_DERIVED (sources + anchors in the file's GOVAI-PROVENANCE header)");
    const restored = [...lines.slice(0, at), `${BASELINE_WIRE_DIGEST}  protocol/wire.ts`, ...lines.slice(at + 1)].join('\n');
    expect(sha256(restored)).toBe(BASELINE_MANIFEST_SHA256);
    expect(sha256(MANIFEST_BYTES)).not.toBe(BASELINE_MANIFEST_SHA256);
  });

  it('keeps the wire.ts GOVAI-PROVENANCE header (lines 1-17) byte-identical and anchors the new entry per entry', () => {
    const text = WIRE_BYTES.toString('utf8');
    expect(sha256(text.split('\n').slice(0, 17).join('\n') + '\n')).toBe(BASELINE_WIRE_HEADER_SHA256);
    expect(splitProvenance(WIRE_BYTES)?.fields.DERIVATION_MODE).toBe('VERBATIM_SOURCE_DERIVED');
    expect(text).toContain(
      "  'experimentalFeature/list': ExperimentalFeatureListResponse; // L1094 response: v2::ExperimentalFeatureListResponse\n",
    );
  });

  it('leaves PIN.ts, pin.test.ts, the lockout, the raw-pipe seam and the schema validator byte-identical to the baseline', () => {
    for (const [rel, digest] of Object.entries(BASELINE_UNTOUCHED)) {
      expect(sha256(readFileSync(join(HARNESS_CODEX_DIR, rel))), rel).toBe(digest);
    }
  });

  it('adds no new file that starts with a GOVAI-PROVENANCE header (static walk): the derived set stays the three baseline files', () => {
    const derived = walk(HARNESS_CODEX_DIR).filter(
      (p) => !p.startsWith('protocol/generated/') && !p.startsWith('pin/vendor/') && splitProvenance(readFileSync(join(HARNESS_CODEX_DIR, p))) !== null,
    );
    expect(derived.sort()).toEqual(['protocol/experimental-inventory.ts', 'protocol/method-names.ts', 'protocol/wire.ts']);
  });
});
